import {labMode} from './lab-mode.mjs';
import {OperationalEngine} from './operational-engine.js';
import {businessPage,servicesPage,bindOperational,operationalStrip} from './operational-ui.js';
import {DemoEngine,SCENARIOS,entity,store,placed,decision,candidates} from './engine.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={monitor:'Global monitor',entities:'Legal entities',customers:'Customer relationships',policy:'Policy studio',generator:'Record generator',technical:'Technical design',business:'Business data model',services:'Business services'};
const groups=['UK','Asia','Americas','MENAT','Europe'];
const labels={'sg-uk-no-us':'Singapore → UK · no US','shared-store-isolation':'Shared store, separate rights','multi-entity':'One owner, multiple recipients','geo-deny':'Entity allowed, geography denied','placement-blocked':'No approved physical placement','no-entitlement':'Residency without entitlement','expired':'Expired grant','contact':'Contact-field projection','short-lived':'20-second entitlement','home-only':'Authoritative relationship only','world-tour':'Global entity workload'};
const descriptions={'sg-uk-no-us':'LE-SG-01 owns the record. LE-GB-02 receives a minimal copy. US storage is explicitly excluded.','shared-store-isolation':'LE-GB-01 shares with LE-GB-02 but excludes LE-GB-03—even though all three use the same London store.','multi-entity':'Separate projections for UK Retail, UK Markets and the French entity. One physical hub, three recipient scopes.','geo-deny':'The Canadian entity is permitted, but its proposed US store violates this customer’s geographic exclusion.','placement-blocked':'India, Germany and Saudi entities have synthetic country-local rules. The three-store PoC cannot place their copies.','no-entitlement':'Entity and country permission exist. An inactive business entitlement prevents sharing.','expired':'The entitlement has expired. No export is allowed.','contact':'Name, tier and email may cross the entity boundary. Confidential notes remain with the owner.','short-lived':'The grant lasts 20 seconds. Reconciliation purges the live projection after expiry.','home-only':'No recipients: keep the entity relationship solely with its authoritative owner.','world-tour':'Rotate through the 25 entities with valid synthetic hub assignments. At most five candidate recipients per record.'};
const designURL='/design/';
let operationalEngine,operationalSpec,opFingerprint='',cat,land=[],state,engine,page=location.hash.slice(1)||'monitor',selected,selectedEntity='LE-GB-02',selectedStore='',group='All',scope='all',query='',stream=null,generating=false,animations=true,formScenario='mixed',formCount=3,formInterval=3,planResult=null,readResult=null,lastError='',busy=false;
const chip=(s,kind='')=>`<span class="chip ${kind}">${esc(s)}</span>`;
const E=id=>entity(cat,id),S=id=>store(cat,id),record=()=>state.customers.find(c=>c.id===selected)||state.customers[0];
const allCopies=()=>state.stores.flatMap(s=>s.replicas);
const point=(lon,lat)=>[(lon+180)/360*1000,(85-lat)/145*440];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4500);}
async function request(path,method='GET',body){const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!response.ok){let error;try{error=await response.json();}catch{}throw Error(error?.detail||`API ${response.status}`);}return response.json();}
async function action(path,body={},method='POST'){try{let result;if(engine){if(path==='/generate')result={created:engine.generate(body.count,body.scenario)};else if(path.endsWith('/pause'))result=engine.pause(path.split('/')[2],body.paused);else if(path.endsWith('/policy'))result=engine.policy(path.split('/')[2],body);else if(path.endsWith('/touch'))result=engine.touch(path.split('/')[2]);else if(path.endsWith('/relationship'))result=engine.relationship(path.split('/')[2],body.owner_entity_id);else if(path.endsWith('/placement-plan'))result=engine.plan(path.split('/')[2],body.store_id);}else result=await request(path,method,body);await refresh(false);return {ok:true,result};}catch(e){toast(e.message);return {ok:false};}}
async function refresh(draw=true){if(engine){const op=operationalEngine.snapshot();state={...engine.state,schema_version:3,operational:op,events:[...engine.state.events,...op.events].sort((a,b)=>b.time-a.time),queue:[...engine.state.queue,...op.queue]};}else{try{state=await request('/state');lastError='';}catch(e){lastError='Live API disconnected. Last known values; no live transfer assurance.';}}if(draw)render();}
function intro(title,sub,actions=''){return `<div class="titlebar"><div><div class="eyebrow">LEGAL ENTITY FEDERATION / EDITION 03</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function metrics(){const denied=state.customers.reduce((n,c)=>n+candidates(c).filter(e=>!decision(c,e,cat).allow).length,0);return `<div class="metrics">${[['Legal entities','30','5 business groups · 25 placeable'],['Record sandbox',state.customers.length,`${new Set(state.customers.map(c=>c.global_customer_id)).size} distinct global customer IDs`],['Blocked candidate routes',denied,'Entity, entitlement or physical placement'],['Pending transfers',state.queue.length,`${allCopies().length} entity-scoped projections present`]].map(([a,b,c])=>`<div class="metric"><div class="metric-label">${a}<span>↗</span></div><div class="metric-value">${b}</div><small>${c}</small></div>`).join('')}</div>`;}
function arc(source,destination){const a=point(S(source).lon,S(source).lat),b=point(S(destination).lon,S(destination).lat);if(source===destination)return `M${a[0]},${a[1]} C${a[0]-75},${a[1]-92} ${a[0]+80},${a[1]-85} ${a[0]},${a[1]}`;const lift=Math.min(145,Math.abs(a[0]-b[0])*.26+30);return `M${a[0]},${a[1]} Q${(a[0]+b[0])/2},${Math.max(10,Math.min(a[1],b[1])-lift)} ${b[0]},${b[1]}`;}
function filteredEvents(){return state.events.filter(e=>(scope!=='selected'||e.record_id===record()?.id)&&(group==='All'||E(e.destination_entity_id)?.group===group));}
function map(){const c=record(),routes=new Map();for(const e of filteredEvents().filter(e=>e.name!=='Projection'&&['replicated','purged'].includes(e.status)).slice(0,50)){const key=e.source_store+e.destination_store+e.status;if(!routes.has(key))routes.set(key,e);}let routeMarkup='';for(const [i,e]of [...routes.values()].slice(0,9).entries()){const path=arc(e.source_store,e.destination_store),age=Date.now()/1000-e.time,recent=age<9;routeMarkup+=`<path class="map-route ${e.status==='purged'?'purged':''} ${!recent?'inactive':''}" d="${path}"/>${recent&&animations?`<circle class="packet ${e.status==='purged'?'purged':''}" r="2.8" style="offset-path:path('${path}');animation-delay:-${(age+i*.6)%3}s"/>`:''}`;}
 if(scope==='selected'&&c){for(const dest of candidates(c)){const d=decision(c,dest,cat);if(!d.allow){const a=E(c.owner_entity_id).store_id,b=E(dest).store_id;routeMarkup+=`<path class="map-route denied" d="${arc(a,b)}"/><text class="stopmark" x="${point(S(a).lon,S(a).lat)[0]+13}" y="${point(S(a).lon,S(a).lat)[1]-8}">×</text>`;}}}
 const lines=[...Array.from({length:11},(_,i)=>`<line class="gridline" x1="${(i+1)*83.333}" x2="${(i+1)*83.333}" y1="0" y2="440"/>`),...Array.from({length:5},(_,i)=>`<line class="gridline" x1="0" x2="1000" y1="${(i+1)*73.333}" y2="${(i+1)*73.333}"/>`)].join('');
 return `<section class="map-panel ${!animations?'animation-off':''}" id="world-panel"><div class="map-head"><div><div class="eyebrow" style="color:#8bbba5">GLOBAL FEDERATION FABRIC</div><h2>${scope==='selected'&&c?esc(c.name):'Thirty entities. Every crossing accounted for.'}</h2><p>${scope==='selected'&&c?`${esc(c.owner_entity_id)} · owner-specific policy · v${c.version} / g${c.generation}`:'Logical entity locations and physical data stores, shown separately.'}</p></div><div class="actions"><button id="scope" class="${scope==='selected'?'on':''}">${scope==='selected'?'◎ All activity':'◉ Focus selected record'}</button><button id="motion" aria-pressed="${!animations}">${animations?'Ⅱ Animation':'▶ Animation'}</button><button id="fullscreen" aria-label="Expand global map">⛶</button></div></div><div class="map-scene"><div class="globe-coordinate">90° W &nbsp; / &nbsp; 0° &nbsp; / &nbsp; 90° E · WGS84</div><svg class="worldmap" viewBox="0 0 1000 440" role="img" aria-label="World map with 30 legal entity locations and three physical store hubs. Animated acknowledged transfers in green, blocked candidate paths dashed red."><title>Global legal entity federation</title>${lines}<g>${land.map(p=>`<path class="land" d="${p}"/>`).join('')}</g>${cat.entities.map(e=>{const [x,y]=point(e.lon,e.lat);return `<circle class="map-point ${!placed(cat,e)?'blocked':''} ${group!=='All'&&group!==e.group?'filtered':''}" data-entity="${e.id}" cx="${x}" cy="${y}" r="3"><title>${e.id} · ${e.city} · ${placed(cat,e)?e.store_id:'No approved placement'}</title></circle>`;}).join('')}<g>${routeMarkup}</g>${state.stores.map(s=>{const [x,y]=point(s.lon,s.lat),labelY=s.region==='UK'?y+28:y-25;return `<g class="store-hit" data-store="${s.id}" tabindex="0" role="button" aria-label="Inspect ${s.city} store"><circle class="store-halo" cx="${x}" cy="${y}" r="18"/><circle class="store-halo" cx="${x}" cy="${y}" r="11"/><circle class="store-core ${s.paused?'paused':''}" cx="${x}" cy="${y}" r="5"/><text class="store-text" x="${x+15}" y="${labelY}">${s.city.toUpperCase()}</text><text class="store-subtext" x="${x+15}" y="${labelY+13}">${s.online?s.replicas.length:'?'} RECORD COPIES · ${s.paused?'PAUSED':'1 NODE'}</text></g>`;}).join('')}</svg><div class="map-note">ENTITY DOTS ≠ DATA LOCATIONS · THREE PHYSICAL HUBS ONLY</div></div><div class="mapfoot"><div class="maplegend"><span><i></i>Acknowledged copy</span><span><i class="amber"></i>Placement blocked</span><span><i class="red"></i>Denied candidate · never sent</span></div><span>Recent-event animation · not packet capture</span></div></section>`;}
function dispatch(){const es=filteredEvents().filter(e=>e.status!=='committed'&&e.name!=='Projection').slice(0,18);return `<aside class="dispatch"><div class="dispatch-head"><div class="live"><span class="dot"></span> DECISION STREAM</div><h2 style="margin-top:12px">Crossings & exclusions</h2><p>Entity → entity / resolved physical store</p></div><div class="dispatch-list">${es.map(e=>`<div class="dispatch-item ${e.status}"><div class="dispatch-item-top"><span>${esc(e.status.replaceAll('_',' ')).toUpperCase()}</span><time>${new Date(e.time*1000).toLocaleTimeString('en-GB')}</time></div><div class="dispatch-route"><b>${esc(e.owner_entity_id)}</b><span class="arrow">${e.status.includes('blocked')?'×':'→'}</span><b>${esc(e.destination_entity_id)}</b></div><p>${esc(e.reason)}</p>${e.dataset?'<div class="entity-sub">OPERATIONAL · '+esc(e.name||e.dataset)+'</div>':''}<div class="entity-sub">${S(e.source_store)?.city} → ${S(e.destination_store)?.city}</div></div>`).join('')||'<div class="empty">Waiting for policy decisions…</div>'}</div></aside>`;}
function groupTiles(){return `<div class="group-strip">${groups.map(g=>`<button class="group-tile ${group===g?'on':''}" data-group="${g}"><span>${g==='Europe'?'REST OF EUROPE':g.toUpperCase()}</span><b>${cat.entities.filter(e=>e.group===g).length}</b><span>legal entities</span></button>`).join('')}</div>`;}
function stores(){return `<div class="store-grid">${state.stores.map(s=>`<section class="store-card ${s.paused?'paused':''} ${selectedStore===s.id?'active':''}" id="store-${s.region}"><div class="store-top"><div class="store-title"><span class="store-code">${s.country}</span><div><h3>${s.city}</h3><p>${s.id}</p></div></div><span class="dot" style="background:${!s.online?'#b8776b':s.paused?'#c5a364':'#5db896'}"></span></div><div class="store-values"><div><b>${cat.entities.filter(e=>e.store_id===s.id&&placed(cat,e)).length}</b><small>valid entity mappings</small></div><div><b>${s.online?s.masters:'—'}</b><small>sandbox owner records</small></div><div><b>${s.online?s.replicas.length:'—'}</b><small>record sandbox copies</small></div></div><div class="store-bottom"><span>1 node · ${s.online?(s.paused?'ingress paused':'available'):'unreachable'}</span><button data-pause="${s.id}" data-value="${!s.paused}">${s.paused?'▶ Resume ingress':'Ⅱ Pause ingress'}</button></div></section>`).join('')}</div>`;}
function recordTable(limit=8){const rows=state.customers.filter(c=>[c.name,c.owner_entity_id,c.global_customer_id,c.scenario].join(' ').toLowerCase().includes(query.toLowerCase())&&(group==='All'||E(c.owner_entity_id).group===group));return `<section class="panel"><div class="panelhead"><div><h2>Record sandbox · entity relationships</h2><p>Global identity, independent ownership, explicit recipients.</p></div>${page==='customers'?`<label class="sr-only" for="search">Search records</label><input type="search" id="search" placeholder="Customer, entity or scenario…" value="${esc(query)}">`:'<a class="link" href="#customers">Inspect all →</a>'}</div><div class="tablewrap"><table><thead><tr><th>Customer / scenario</th><th>Owner entity</th><th>Recipients present</th></tr></thead><tbody>${rows.slice(0,limit).map(c=>`<tr data-select="${c.id}" tabindex="0" class="${selected===c.id?'selected':''}" aria-label="Inspect ${esc(c.name)} owned by ${c.owner_entity_id}"><td><div class="name">${esc(c.name)}</div><div class="id">${esc(c.scenario)}</div></td><td>${chip(c.owner_entity_id)}<div class="entity-sub">${S(E(c.owner_entity_id).store_id).city}</div></td><td>${allCopies().filter(p=>p.record_id===c.id).map(p=>chip(p.destination_entity_id,decision(c,p.destination_entity_id,cat).allow?'':'wait')).join('')||'<span class="tiny">No projections</span>'}</td></tr>`).join('')}</tbody></table></div><div class="tablefoot"><span>${Math.min(rows.length,limit)} of ${rows.length} relationships ${group!=='All'?'· '+group:''}</span><span>Owner + global customer ID</span></div></section>`;}
function inspector(){const c=record();if(!c)return '';const copies=allCopies().filter(p=>p.record_id===c.id),siblings=state.customers.filter(d=>d.global_customer_id===c.global_customer_id&&d.id!==c.id);return `<section class="panel"><div class="panelhead"><h2>Relationship inspector</h2>${chip('v'+c.version+' / g'+c.generation)}</div><div class="inspector"><div class="eyebrow">${esc(c.owner_entity_id)} / AUTHORITATIVE OWNER</div><h3>${esc(c.name)}</h3><div class="entity-key">Global ID: ${c.global_customer_id}</div><div class="detailgrid"><div><label>Owner entity</label><b>${esc(E(c.owner_entity_id).name)}</b></div><div><label>Physical store</label><b>${S(E(c.owner_entity_id).store_id).city} · ${S(E(c.owner_entity_id).store_id).country}</b></div><div><label>Tier</label><b>${esc(c.tier)}</b></div><div><label>Other owner relationships</label><b>${siblings.length}</b></div></div>${siblings.length?`<div class="policybanner">Same global ID also belongs to ${siblings.map(d=>esc(d.owner_entity_id)).join(', ')}. These records retain separate policy and authority.</div>`:''}<div class="inspector-label">Current route decisions</div>${candidates(c).map(dest=>{const d=decision(c,dest,cat);return `<div class="route-card"><div class="route-card-top"><span>${dest}</span>${chip(d.allow?'ALLOW':d.reason.includes('placement')?'NO PLACEMENT':'DENY',d.allow?'':d.reason.includes('placement')?'wait':'denied')}</div><p>${esc(d.reason)}</p><div class="location">${E(dest).country} legal entity → ${S(E(dest).store_id).city} store (${S(E(dest).store_id).country})</div></div>`;}).join('')||'<p class="tiny">Home only. No candidate recipients.</p>'}<div class="inspector-label">Copies actually present</div>${copies.map(p=>`<div class="fieldrow"><span>${p.destination_entity_id}<br><small>${p.store_id} · v${p.version}</small></span><code>${Object.keys(p.fields).join(', ')}</code></div>`).join('')||'<p class="tiny">No remote entity projections.</p>'}${copies.some(p=>!decision(c,p.destination_entity_id,cat).allow)?'<div class="notice">Access is denied, but a live copy remains. Purge is pending acknowledgement; this is not completed deletion.</div>':''}<div class="actions"><button data-touch="${c.id}">↻ Update owner record</button><button id="editpolicy">Edit policy →</button></div><div class="inspector-label">Verify entity access</div><div class="actions"><select id="readentity" style="margin:0;font-size:10px">${cat.entities.map(e=>`<option value="${e.id}" ${e.id==='LE-GB-02'?'selected':''}>${e.id} · ${e.city}</option>`).join('')}</select><button id="testread">Test business read</button></div>${readResult?`<div class="rulebox">${esc(readResult)}</div>`:''}${page==='customers'?`<div class="inspector-label">Add independent owner relationship</div><select id="relationshipowner">${cat.entities.filter(e=>placed(cat,e)&&e.id!==c.owner_entity_id).map(e=>`<option>${e.id}</option>`).join('')}</select><button id="relationship" style="margin-top:10px">＋ Create synthetic relationship</button><p class="tiny" style="margin-top:8px">Requires permission to disclose the global ID. Fresh synthetic fields and grants; geographic restrictions are preserved.</p>`:''}</div></section>`;}
function queue(){return `<section class="panel"><div class="panelhead"><h2>Reconciliation queue</h2>${chip(state.queue.length,'wait')}</div>${state.queue.slice(0,8).map(q=>`<div class="queueitem">${q.source_store} → ${q.destination_entity_id} ${chip(q.status,'wait')}<small>${esc(q.reason||'Awaiting source policy evaluation')} · attempt ${q.attempts}</small></div>`).join('')||'<div class="empty">✓ All queued work has settled.</div>'}</section>`;}
function registry(){const rows=cat.entities.filter(e=>(group==='All'||e.group===group)&&[e.id,e.name,e.country,e.group].join(' ').toLowerCase().includes(query.toLowerCase()));return intro('Legal entity directory','Thirty legal entities. Explicit physical placement. No implied sharing between neighbours.',`<button id="cleargroup">${group==='All'?'All 30 entities':'Clear '+group+' filter'}</button>`)+`<div class="pagecall"><b>Illustrative allocation:</b> UK 3 · Asia 8 · Americas 3 · MENAT 5 · rest of Europe 11. Countries, entity names and residency rules are synthetic design fixtures—not a legal assessment.</div>`+groupTiles()+`<div class="content-grid"><section class="panel"><div class="panelhead"><h2>Entity → physical store registry</h2><div class="registry-filter"><input type="search" id="search" value="${esc(query)}" placeholder="Find entity or country…"></div></div><div class="tablewrap"><table class="registry-table"><thead><tr><th>Legal entity</th><th>Country / group</th><th>Candidate store</th><th>Placement</th></tr></thead><tbody>${rows.map(e=>`<tr data-entity="${e.id}" tabindex="0" class="${e.id===selectedEntity?'selected':''}"><td><div class="entity-name">${e.id}</div><div class="entity-sub">${e.name}</div></td><td>${e.country}<div class="entity-sub">${e.group}</div></td><td>${S(e.store_id).city}<div class="entity-sub">${e.store_id}</div></td><td>${chip(placed(cat,e)?'APPROVED':'BLOCKED',placed(cat,e)?'':'wait')}</td></tr>`).join('')}</tbody></table></div><div class="tablefoot"><span>${rows.length} entities shown</span><span>Directory version ${cat.version}</span></div></section>${entityInspector()}</div>`;}
function entityInspector(){const e=E(selectedEntity);return `<section class="panel"><div class="panelhead"><h2>Placement inspector</h2>${chip(e.id)}</div><div class="inspector"><div class="eyebrow">${e.group} / ${e.country}</div><h3>${e.name}</h3><p class="subtitle">${e.city} · legal entity location</p><div class="detailgrid"><div><label>Candidate physical store</label><b>${S(e.store_id).city} (${S(e.store_id).country})</b></div><div><label>Placement generation</label><b>p${e.placement_version}</b></div><div><label>Approved storage countries</label><b>${e.approved_countries.join(', ')}</b></div><div><label>Policy fixture</label><b>${e.rule}</b></div></div><div class="${placed(cat,e)?'policybanner':'notice'}">${placed(cat,e)?'This synthetic entity may use its assigned hub. Every recipient relationship still needs its own entitlement.':'No valid placement: the candidate store is outside the approved countries. No owner records or inbound copies may be created for this entity.'}</div><div class="inspector-label">Current footprint</div><div class="fieldrow"><span>Authoritative relationships</span><b>${state.customers.filter(c=>c.owner_entity_id===e.id).length}</b></div><div class="fieldrow"><span>Recipient projections</span><b>${allCopies().filter(p=>p.destination_entity_id===e.id).length}</b></div><div class="inspector-label">Plan a store relocation</div><select id="targetstore">${cat.stores.map(s=>`<option value="${s.id}" ${s.id===e.store_id?'selected':''}>${s.city} · ${s.id}</option>`).join('')}</select><button id="planplacement" style="margin-top:12px">Simulate placement impact</button><p class="tiny" style="margin-top:9px">Read-only impact plan. This does not move data or change the directory.</p>${planResult&&planResult.entity_id===e.id?`<div class="notice"><b>${planResult.approved?'Eligible for a migration proposal':'Placement rejected'}</b><br>${planResult.affected_records} affected relationships · ${planResult.conflicting_records.length} customer conflicts<br>Entity country rule: ${planResult.entity_country_allowed?'satisfied':'violated'}</div><div class="approval-path">${planResult.stages.map((s,i)=>`<span>${i+1}. ${s}</span>`).join('')}</div><p class="tiny">Execution, rollback and approval workflow are engineering extension points.</p>`:''}</div></section>`;}
function policyPage(){const c=record();return intro('Policy studio','Authorise the recipient entity. Validate its physical store. Apply exclusions before export.')+`<div class="content-grid"><section class="panel"><div class="panelhead"><div><h2>Entity + geography policy</h2><p>OPA/Rego v1 in the local runtime · equivalent simulation in this hosted demo</p></div>${chip('DENY OVERRIDES')}</div><div class="pad"><label class="fieldlabel" for="policycustomer">Owner relationship</label><select id="policycustomer">${state.customers.map(d=>`<option value="${d.id}" ${d.id===c.id?'selected':''}>${esc(d.name)} · ${d.owner_entity_id} · ${d.scenario}</option>`).join('')}</select><div class="inspector-label">Physical geography constraints</div><div class="geo-rules">${cat.stores.map(s=>`<div class="geo-rule"><b>${s.name} · ${s.country}</b><label><input type="checkbox" id="country-allow-${s.country}" ${c.allowed_countries.includes(s.country)?'checked':''}> Approved storage country</label><label><input type="checkbox" id="country-deny-${s.country}" ${c.denied_countries.includes(s.country)?'checked':''}> Explicitly exclude</label></div>`).join('')}</div><div class="inspector-label">Recipient legal entities</div><div class="policy-scroll"><table class="policy-table"><thead><tr><th>Recipient / physical store</th><th>Allow</th><th>Exclude</th><th>Grant</th><th>Placement</th></tr></thead><tbody>${cat.entities.filter(e=>e.id!==c.owner_entity_id).map(e=>`<tr><td>${e.id}<div class="entity-sub">${e.country} entity → ${S(e.store_id).city}</div></td><td><input aria-label="Allow ${e.id}" type="checkbox" id="allow-${e.id}" ${c.allowed_entities.includes(e.id)?'checked':''}></td><td><input aria-label="Exclude ${e.id}" type="checkbox" id="deny-${e.id}" ${c.denied_entities.includes(e.id)?'checked':''}></td><td><input aria-label="Entitle ${e.id}" type="checkbox" id="grant-${e.id}" ${c.grants[e.id]?.active?'checked':''}></td><td>${chip(placed(cat,e)?'valid':'blocked',placed(cat,e)?'':'wait')}</td></tr>`).join('')}</tbody></table></div><div class="formgrid"><label>Profile for checked grants<select id="profile"><option value="minimal">Minimal · name + tier</option><option value="contact">Contact · name + tier + email</option></select></label><label>Renew checked grants for<select id="ttl"><option value="86400">24 hours</option><option value="20">20 seconds · expiry test</option><option value="300">5 minutes</option></select></label></div><div class="policybanner">Owner ${c.owner_entity_id} stays authoritative. Applying this form updates entity and geographic rules and renews checked grants with the selected profile. It cannot override entity placement restrictions.</div><div class="actions" style="margin-top:17px"><button class="primary" id="savepolicy" data-generation="${c.generation}">Apply & reconcile</button><span class="tiny">Compare-and-set generation g${c.generation}</span></div></div></section>${inspector()}</div>`;}
function generator(){return intro('Record generator','Exercise entity sharing, physical placement and customer exclusions with synthetic workloads.')+`<div class="content-grid"><section class="panel"><div class="panelhead"><h2>Generate a federation workload</h2>${chip(stream?'STREAM RUNNING':'READY')}</div><div class="pad"><div class="formgrid"><label>Scenario<select id="scenario"><option value="mixed">Mixed · all 11 scenarios</option>${SCENARIOS.map(s=>`<option value="${s}" ${formScenario===s?'selected':''}>${labels[s]}</option>`).join('')}</select></label><label>Records per batch<input id="count" type="number" min="1" max="100" value="${formCount}"></label><label>Stream interval (seconds)<input id="interval" type="number" min="1" max="60" value="${formInterval}"></label><div><span class="fieldlabel">Model coverage</span><p class="subtitle" style="margin-top:10px">30 entities · 3 stores · 5 placement conflicts<br>Global IDs with independent owner relationships</p></div></div><div class="actions"><button class="primary" id="generate">＋ Generate batch</button><button id="stream">${stream?'■ Stop stream':'▶ Start stream'}</button><a class="link" href="#monitor">Watch global movement →</a></div><div class="notice">Streams run while this tab remains open. Use the included CLI generator for repeatable workloads against the real local runtime.</div></div></section>${queue()}</div><div class="eyebrow">ELEVEN ENGINEERED SCENARIOS</div><div class="scenario-grid">${SCENARIOS.map(s=>`<article class="scenario"><h3>${labels[s]}</h3><p>${descriptions[s]}</p><button data-scenario="${s}">Generate example ↗</button></article>`).join('')}</div>`;}
const components=[['performance-scale','Performance at scale','Simulated capacity, p95/p99 targets and 100M relationship sizing.'],['pilot-plan','PoC to pilot','Prioritised actions, owners and evidence gates.'],['operational-model','Operational business model','Party, relationships, holdings and all 12 table mappings.'],['sovereignty-integration','Parallel sovereignty controls','Table defaults, major keys and resource constraints.'],['service-transactions','Business services & transactions','Regional gateways, unit of work, APIs and performance choices.'],['entity-model','Entity model','Global identity, authoritative owner and recipient-specific projections.'],['placement','Placement directory','Versioned bindings, country rules and controlled migration.'],['opa','OPA decisions','Entity permissions intersected with physical geography and grants.'],['gateways','Business APIs','Resolve authenticated entity context before routing to its physical store.'],['transactions','Transactions','Local owner commits and separate idempotent projection transactions.'],['federation','Federation pipeline','Source-only outbox, export gate and destination-bound admission.'],['lifecycle','Revocation & migration','Source block, read denial, pending purge and retained history.'],['observability','OpenTelemetry','Regional collection and low-cardinality entity/store signals.'],['audit','Audit evidence','Source entity, destination entity, store and policy receipts.'],['engineering','Engineering prompts','Concrete component tasks, acceptance tests and extension points.']];
function technical(){return intro('Architecture & engineering','The legal entity is the federation boundary. The store is a separately governed deployment target.',`<a class="primary" style="padding:10px 14px;border-radius:6px" href="https://github.com/paulcull/sovereign-federation-lab">Source repository ↗</a>`)+`<div class="pagecall"><b>Two experiences, one design:</b> this monitor provides an interactive synthetic PoC. The architecture companion provides separate component pages, diagrams, API contracts and engineering prompts.</div><div class="technical"><section class="panel"><div class="panelhead"><h2>Identity → ownership → physical placement</h2></div><div class="pad"><div class="code">global_party_id = shared identity (approved minimum)\nowner_entity_id + relationship_id = relationship root\nowner + scope + recipient_entity + row_id = projection key\nregistered table + resource_id → separate sovereignty rules\nrecipient_entity → versioned physical store</div><p style="margin-top:15px">A shared customer ID does not combine rights. A shared London database does not grant one UK entity access to another entity’s rows.</p></div></section><section class="panel"><div class="panelhead"><h2>Three real-node runtime · thirty entity policies</h2></div><div class="pad"><p>The downloadable PoC runs three independent CockroachDB nodes and three OPA processes. One FastAPI harness coordinates entity-scoped tables, outbox polling and telemetry. Geographic labels are logical on one machine.</p><div class="notice">Hosted mode is an in-memory browser simulation. The real Compose stack still requires local end-to-end verification; the execution environment could not start CockroachDB.</div></div></section><section class="panel"><div class="panelhead"><h2>Start locally</h2></div><div class="pad"><div class="code">unzip sovereign-data-poc.zip\ncd sovereign-data-poc\ndocker compose up --build\n# Open http://localhost:8000\npython3 poc/scripts/generate.py --scenario world-tour --count 10\npython3 poc/tests/integration.py\npython3 poc/tests/operational_integration.py\npython3 poc/scripts/business_commands.py --command open_holding --count 5</div><p style="margin-top:12px">New <code>business.*</code>, <code>sovereignty.*</code> and <code>projection.*</code> schemas sit alongside the earlier <code>fe_*</code> record sandbox. One worker only; no local HA, authentication or TLS.</p></div></section><section class="panel"><div class="panelhead"><h2>Trade-offs made deliberately</h2></div><div class="pad"><ul><li>Serializable owner write + outbox; async destination projection.</li><li>Physical placement validated before export, even within a shared hub.</li><li>Single harness lock for correctness in this thin PoC; distributed fencing remains an extension.</li><li>Read-only migration planner; no unsafe live routing switch.</li><li>Rego controls export; business reads reauthorize against current owner policy.</li><li>OTel traces and regional audit remain separate.</li></ul></div></section></div><div class="eyebrow" style="margin-top:28px">COMPONENT DESIGN PAGES</div><div class="design-links">${components.map(([slug,title,description])=>`<a class="design-link" href="${designURL+slug}.html" target="_blank" rel="noopener"><strong>${title} ↗</strong><p>${description}</p></a>`).join('')}</div>`;}
function render(){if(!state)return;if(!titles[page])page='monitor';if(!selected)selected=state.customers.find(c=>c.scenario==='sg-uk-no-us')?.id||state.customers[0]?.id;$('#crumb').textContent=titles[page];$('#connection').textContent=lastError?'API disconnected':engine?'Browser simulation':'Live local runtime';$('#modebar').classList.toggle('api-error',!!lastError);$('#modebar').innerHTML=lastError?esc(lastError):engine?'<strong>BROWSER SIMULATION</strong> · 30 synthetic legal entities / 3 physical store models. No bank data. Reload resets the demo. Use the container pilot for real CockroachDB + OPA.':'<strong>LIVE BACKEND</strong> · Business data comes from the API. The connection strip shows the active footprint. Store geographies are logical labels on one host.';$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));if(page==='monitor')$('#main').innerHTML=intro('Sovereign Data Monitor','Follow the legal entity. Verify the geography. Account for every copy.',`<button id="showcase">${stream?'■ Stop showcase':'▶ Run showcase'}</button><button class="primary" id="quickgenerate">＋ Generate records</button>`)+metrics()+operationalStrip(state.operational)+`<div class="global-layout">${map()}${dispatch()}</div>`+groupTiles()+stores()+`<div class="content-grid"><div>${recordTable()}${queue()}</div>${inspector()}</div>`;if(page==='entities')$('#main').innerHTML=registry();if(page==='customers')$('#main').innerHTML=intro('Customer relationships','The same global customer can have several authoritative entity relationships.',`<button id="cleargroup">${group==='All'?'All entities':'Clear '+group+' filter'}</button>`)+`<div class="content-grid">${recordTable(500)}${inspector()}</div>`;if(page==='policy')$('#main').innerHTML=policyPage();if(page==='generator')$('#main').innerHTML=generator();if(page==='technical')$('#main').innerHTML=technical();if(page==='business')$('#main').innerHTML=businessPage(state.operational,cat);if(page==='services')$('#main').innerHTML=servicesPage(state.operational,cat,state.stores,!engine);bind();bindOperational({op:()=>state.operational,render,refresh:()=>refresh(false),toast,command:(sid,body)=>engine?operationalEngine.command(sid,body):request(`/operational/scopes/${sid}/commands`,'POST',body),preview:(sid,dest)=>engine?operationalEngine.preview(sid,dest):request(`/operational/scopes/${sid}/preview/${dest}`),read:(sid,dest)=>engine?operationalEngine.read(sid,dest):request(`/operational/scopes/${sid}/read/${dest}`),map:()=>{scope='all';group='All';location.hash='monitor';}});}
async function generateBatch(){if(generating)return;generating=true;const r=await action('/generate',{count:formCount,scenario:formScenario});generating=false;if(r.ok){if(!stream)toast(`${r.result.created.length} owner relationships committed; candidate routes queued.`);render();}}
function toggleStream(showcase=false){if(stream){clearInterval(stream);stream=null;toast('Generator stopped. Queued work continues.');}else{if(showcase){formCount=1;formInterval=2;formScenario='mixed';scope='all';group='All';}stream=setInterval(generateBatch,formInterval*1000);generateBatch();toast('Workload streaming. Watch the global monitor.');}render();}
function onKeyClick(el,fn){el.onclick=fn;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn();}};}
function bind(){$$('[data-select]').forEach(el=>onKeyClick(el,()=>{selected=el.dataset.select;scope='selected';readResult=null;render();}));$$('[data-entity]').forEach(el=>onKeyClick(el,()=>{selectedEntity=el.dataset.entity;planResult=null;if(page!=='entities'){group='All';query='';location.hash='entities';}else render();}));$$('[data-store]').forEach(el=>onKeyClick(el,()=>{selectedStore=el.dataset.store;render();$(`#store-${S(selectedStore).region}`)?.scrollIntoView({behavior:'smooth',block:'nearest'});}));$$('[data-group]').forEach(el=>el.onclick=()=>{group=group===el.dataset.group?'All':el.dataset.group;render();});if($('#cleargroup'))$('#cleargroup').onclick=()=>{group='All';render();};$$('[data-pause]').forEach(el=>el.onclick=async()=>{await action(`/stores/${el.dataset.pause}/pause`,{paused:el.dataset.value==='true'});render();});$$('[data-touch]').forEach(el=>el.onclick=async()=>{if((await action(`/records/${el.dataset.touch}/touch`)).ok)toast('Owner version advanced; entity projections queued.');render();});if($('#scope'))$('#scope').onclick=()=>{scope=scope==='all'?'selected':'all';render();};if($('#motion'))$('#motion').onclick=()=>{animations=!animations;$('#world-panel').classList.toggle('animation-off',!animations);$('#motion').textContent=animations?'Ⅱ Animation':'▶ Animation';$('#motion').setAttribute('aria-pressed',String(!animations));};if($('#fullscreen'))$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#world-panel').requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser.');}};if($('#showcase'))$('#showcase').onclick=()=>toggleStream(true);if($('#quickgenerate'))$('#quickgenerate').onclick=async()=>{const r=await action('/generate',{count:3,scenario:'mixed'});if(r.ok)toast('3 new relationships. Follow the decision stream.');render();};if($('#editpolicy'))$('#editpolicy').onclick=()=>location.hash='policy';if($('#search'))$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#policycustomer'))$('#policycustomer').onchange=e=>{selected=e.target.value;readResult=null;render();};if($('#savepolicy'))$('#savepolicy').onclick=savePolicy;if($('#scenario'))$('#scenario').onchange=e=>formScenario=e.target.value;if($('#count'))$('#count').onchange=e=>formCount=Math.max(1,Math.min(100,Number(e.target.value)||1));if($('#interval'))$('#interval').onchange=e=>formInterval=Math.max(1,Math.min(60,Number(e.target.value)||3));if($('#generate'))$('#generate').onclick=generateBatch;if($('#stream'))$('#stream').onclick=()=>toggleStream();$$('[data-scenario]').forEach(el=>el.onclick=async()=>{const r=await action('/generate',{count:1,scenario:el.dataset.scenario});if(r.ok){selected=r.result.created[0].id;toast('Created: '+labels[el.dataset.scenario]);render();}});if($('#planplacement'))$('#planplacement').onclick=async()=>{const r=await action(`/entities/${selectedEntity}/placement-plan`,{store_id:$('#targetstore').value});if(r.ok){planResult=r.result;render();}};if($('#relationship'))$('#relationship').onclick=async()=>{const r=await action(`/records/${record().id}/relationship`,{owner_entity_id:$('#relationshipowner').value});if(r.ok){selected=r.result.id;toast('Independent owner relationship created; existing grants were not copied.');render();}};if($('#testread'))$('#testread').onclick=testRead;}
async function savePolicy(){const c=record(),allowed_entities=[],denied_entities=[],grants={},allowed_countries=[],denied_countries=[];for(const e of cat.entities.filter(e=>e.id!==c.owner_entity_id)){if($(`#allow-${e.id}`).checked)allowed_entities.push(e.id);if($(`#deny-${e.id}`).checked)denied_entities.push(e.id);if($(`#grant-${e.id}`).checked||c.grants[e.id])grants[e.id]={active:$(`#grant-${e.id}`).checked,expires_at:Date.now()/1000+Number($('#ttl').value),profile:$('#profile').value,purpose:'servicing'};}for(const s of cat.stores){if($(`#country-allow-${s.country}`).checked)allowed_countries.push(s.country);if($(`#country-deny-${s.country}`).checked)denied_countries.push(s.country);}const r=await action(`/records/${c.id}/policy`,{expected_generation:Number($('#savepolicy').dataset.generation),allowed_entities,denied_entities,grants,allowed_countries,denied_countries},'PATCH');if(r.ok){toast('Policy applied. Read access changes now; stored copies reconcile asynchronously.');render();}}
async function testRead(){const c=record(),dest=$('#readentity').value;try{let data;if(engine){if(dest===c.owner_entity_id)data={fields:{name:c.name,tier:c.tier,email:c.email,notes:c.notes}};else{const d=decision(c,dest,cat);if(!d.allow)throw Error('403 denied · '+d.reason);data=allCopies().find(p=>p.record_id===c.id&&p.destination_entity_id===dest);if(!data)throw Error('404 projection not ready');if(data.generation!==c.generation)throw Error('409 awaiting current policy generation');}}else data=await request(`/records/${c.id}/read/${dest}`);readResult=`${dest}: access allowed · ${Object.keys(data.fields||{name:1,tier:1,email:1,notes:1}).join(', ')}`;}catch(e){readResult=`${dest}: ${e.message}`;}render();}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'monitor';query='';render();window.scrollTo(0,0);});$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='sovereign-entity-snapshot.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{[cat,land,operationalSpec]=await Promise.all([fetch('catalog.json').then(r=>r.json()),fetch('land.json').then(r=>r.json()),fetch('operational.json').then(r=>r.json())]);if(await labMode()==='live'){state=await request('/state');if(state.schema_version!==3)throw Error('This UI requires the v3 operational runtime. Rebuild the local container.');}else{engine=new DemoEngine(cat);operationalEngine=new OperationalEngine(cat,operationalSpec);await refresh(false);}animations=!matchMedia('(prefers-reduced-motion: reduce)').matches;render();setInterval(async()=>{if(busy)return;busy=true;try{if(engine){engine.tick();operationalEngine.tick(engine.state.stores);}await refresh(false);const fp=JSON.stringify([state.operational.model.scopes.map(s=>[s.data_version,s.decision_revision,s.policy_generation]),state.operational.projections.map(p=>[p.scope_id,p.destination_entity_id,p.data_version,p.decision_revision]),state.operational.queue.length]);if(['services','business'].includes(page)&&fp!==opFingerprint&&!['INPUT','SELECT'].includes(document.activeElement?.tagName)){opFingerprint=fp;render();}if(page==='monitor'&&!document.fullscreenElement&&document.activeElement?.tagName!=='SELECT'){const active=document.activeElement?.id,scroll=$('.dispatch-list')?.scrollTop;render();if(active)$('#'+active)?.focus({preventScroll:true});if(scroll&&$('.dispatch-list'))$('.dispatch-list').scrollTop=scroll;}else if(document.fullscreenElement){const old=$('.map-scene'),tmp=document.createElement('div');tmp.innerHTML=map();old.innerHTML=tmp.querySelector('.map-scene').innerHTML;bind();}if(lastError){$('#modebar').textContent=lastError;$('#modebar').classList.add('api-error');}}finally{busy=false;}},850);}catch(e){$('#modebar').textContent='Runtime unavailable';$('#main').innerHTML=intro('Unable to connect',esc(e.message))+`<div class="panel pad"><p>For the real runtime, run <code>./lab up</code> and wait for the API. This local screen does not silently switch to simulation.</p><button onclick="location.reload()" style="margin-top:15px">Retry connection</button></div>`;}
